        '21531',
        'Fill missing days',
        'fill missing days',
        'Dear Rwaina,    Based on our web session, kindly find below the status:      • Issue Reported by the customer: Fill missing days.    • Status: Solved.    • Problem description: The ETL daily fill process failed due to the following:    1- April 02, 2026 Issue:  The column LEDGER_CODE in the core database table AML_TRANSACTIONS was returning NULL for the following record:  • CLIENT_ID: 450186.  • APPLICATION_NO: 6344000006.  • TRANS_DATE: 02-APR-2026.   Please note that LEDGER_CODE cannot be NULL in the Data Warehouse table BI_DWH.PIO_TRANSACTIONS.         2- Subsequent Missing Dates (from April 03, 2026 onward):  The ETL daily job failed due to changes in the server credentials for the user account “ETL-APP\comadmin”, as indicated in the error below.         3- Tablespace Capacity Issue:  Insufficient tablespace availability at the Data Warehouse level contributed to the ETL failures.         • Action Taken – recommended solution: Based on our web session, kindly to be informed that the issue was resolved by:    1- LEDGER_CODE NULL Issue:  A workaround was applied to fill the NULL LEDGER_CODE in the Data Warehouse with a default value of 0 for the affected record, since the source returned NULL.    2- Credential Issue:  The issue was resolved from your side by updating the new credentials for the user account “ETL-APP\comadmin” in the ETL Windows Task Scheduler.    3- Tablespace Issue:  All required tablespaces were extended to maintain at least 50 GB or 30% of free space.    4- Missing Dates Recovery:  he ETL daily fill process was successfully re-executed for all missing dates from April 02, 2026 until today, and the AML alerts has been fully generated.    Kindly check from your side and confirm to close this ticket.     Best Regards,',
