        '21542',
        'Empty Branches on Reports',
        'Empty Branches on Reports',
        'Dear @Oula.michel,    Based on our web session, kindly find below the status:     • Issue Reported by the customer: Empty Branches on Reports.     • Status: Solved.     • Problem description: The Branch Name was appearing as blank in most of both Closed and Open Reports.    • Action Taken – recommended solution: Based on our web session, please note that the issue was identified as being related to the procedure logic, specifically due to a mismatch in the DAY_DATE used when retrieving branch data.    The procedure has been enhanced by introducing a variable to store the maximum DAY_DATE from the branches table and using it to retrieve the latest available branch information.    As a result, the missing branch names are now displayed correctly in the reports without any issues.    Kindly check from your side and confirm so we can proceed with closing this ticket.',
