        '21536',
        'Re-activating the delete retention process on the BI_ODS Schema.',
        'Re-activating the delete retention process on the BI_ODS Schema.',
        'Dear Oula,    Based on our web session, kindly find below the status:      • Issue Reported by the customer: Re-activating the delete retention process on the BI_ODS Schema..    • Status: Solved.    • Problem description: The BI_ODS schema was retaining more than 75 days of data due to the delete retention job being disabled. This led to significant database growth and negatively impacted the daily fill process and overall table performance, considering that the ODS is designed to retain only 5–7 days of data.    • Action Taken – recommended solution: Based on our web session, the issue has been resolved by truncating specific tables to remove the excess data and clean up the ODS schema. This action freed up approximately 289 GB of storage. Additionally, the delete retention process has been successfully re-activated.    Kindly check from your side and confirm to close this ticket.     Best Regards,',
