        'Screening Issue – EU Listed Names',
        'Dear team     Please be informed that, as part of our quality assurance procedures and periodic review of recently added names, we conducted a verification process on a number of entries listed on the EU sanctions lists.  During this process, we identified that some EU-listed names did not return any results when checked against the screening search provided by your system, despite being confirmed as listed on the EU sanctions lists.    Please note that a sample list of these names is attached for your reference, highlighting the cases that did not appear in the screening results.    We kindly request that you urgently investigate this issue and provide a clear explanation for this discrepancy. This matter represents a critical failure in the screening system, as any inability to detect listed names poses a significant and unacceptable risk.    Such gaps may result in listed entities passing through undetected, which could expose us to serious regulatory consequences, including substantial fines and compliance breaches—particularly in light of the upcoming Mastercard visit.  Given the seriousness of this issue, your immediate attention and prompt response are required.',
