        'ETL issue',
        'Dear Team,  ETL job for compliance has failed.  Kindly provide your support',
        'Dear Aya,    Based on our web session, kindly find below the status:      • Issue Reported by the customer: ETL issue.    • Status: Solved.    • Problem description: The Compliance ETL daily job failed because the BI_ODS schema was retaining more than 75 days of data, due to the delete retention process not being applied on the new AML database. This resulted in significant database growth and negatively impacted the daily fill process and overall table performance, noting that the ODS is designed to retain only 5–7 days of data    • Action Taken – recommended solution: Based on our web session, the issue has been resolved by truncating specific tables to remove excess data and clean up the BI_ODS schema. This action freed approximately 300 GB of storage space.         Additionally, the delete retention process has been successfully activated, and maintenance jobs (Gather Statistics) have been created for both BI_ODS and BI_DWH schemas.    Furthermore, the Compliance ETL job was successfully completed after rebuilding indexes on the affected tables, executing the Gather Statistics maintenance jobs, and re-running the daily fill process from the point of failure.          Kindly check from your side and confirm to close this ticket.     Best Regards,',
