(
        '21540',
        'Issue with Screening Match',
        '•False Match Observation: The name ABDULLAH ALBAYED matched with SALEH SALEH (AKA of ABDULLA SALEH ABDULAA ALALFI) in the live environment',
        'Dear @Ayah Alsmadi,  With regard to the reported observation of a potential false match between “ABDULLAH ALBAYED” and “SALEH SALEH”, we would like to clarify the following:  Please note that the system is using a fuzzy matching algorithm, which does not rely only on exact name matching. Instead, it evaluates similarities between name components and also considers any associated AKA (Also Known As) names linked to the screened entities.  In this case, “SALEH SALEH” is registered as an AKA for the individual “Abdullah Ahmed Abdullah El Alfi”. As a result, the system identified a match based on both the fuzzy logic and the presence of overlapping name elements.  Therefore, this behavior is expected and does not indicate a system issue. It is part of the designed screening logic to ensure comprehensive coverage and avoid missing potential matches.  Please let us know if you need any further clarification.',
        '2026-04-21T00:00:00.000Z'::timestamptz,
        '2026-04-12T00:00:00.000Z'::timestamptz,
