        '21648',
        'Fix Tomcat vulnerabilities',
        'Please find below the status update regarding the reported vulnerabilities related to Internal-Penetration-Testing-BI (003):    1.Python Unsupported Version Detection  This finding is not applicable to SAP BusinessObjects (SAP BO) and therefore considered not relevant.    2.Apache Tomcat 9.0.83 < 9.0.115  Since OCSP (Online Certificate Status Protocol) is not in use, SAP BusinessObjects is not impacted by this vulnerability.    3.HSTS Missing From HTTPS Server (RFC 6797)  The attached filter should be implemented in the web.xml configuration file to enforce HSTS policy.    4.Apache Tomcat Default Files  Default and example pages in Apache Tomcat should be removed to eliminate this vulnerability from being flagged.',
        'Dear @Azher Jawher,    Based on our web session, kindly find below the status:     • Issue Reported by the customer: Fix Tomcat vulnerabilities .      • Status: Done.     • Problem description: Fix Tomcat vulnerabilities .    • Action Taken – recommended solution: Based on our web session, please note that the Default and example pages in Apache Tomcat have been removed and The filter have been implemented in the web.xml configuration file .    ? Kindly check and confirm so we may proceed with closing the ticket.',
