        'Issue on new customer screening',
        'Dear Team    Further to your previous response confirming that the issue has been resolved and that all customer names have been screened, I have reviewed the records and can confirm that the listed names are still not screened.    The customer names remain unscreened. In addition, some customers who opened accounts on 20 April 2026 also remain unscreened.    Moreover, we have identified several recurring and critical issues that require your immediate attention:  • There are repeated instances where the screening process is not performed three times per day as agreed.  • The delta screening (twice daily) is inconsistently executed, with instances where one or both runs are missing.  • On 21 April 2026, no new customers were screened at all, and the report showed 0 results. All customers were later processed in bulk on 22 April 2026, which is not aligned with the agreed process.  • These are not isolated incidents but recurring operational failures.  This situation is unacceptable.  The failure to consistently and correctly screen new customers represents a high-risk exposure, which may lead to serious regulatory consequences, including penalties and compliance breaches. As you are aware, this level of inconsistency cannot be tolerated.  We require the following without delay:  1.A root cause analysis explaining why these recurring issues are occurring.  2.A permanent and robust solution to ensure this does not happen again.  3.Confirmation that the screening process will strictly adhere to the agreed frequency and standards moving forward.  4.Implementation of a real-time monitoring and alert mechanism to immediately flag any failure or interruption in the screening process, instead of placing the responsibility on us to manually verify the process on a daily basis.   This matter has now escalated beyond acceptable operational limits. The repetition of these failures indicates a serious gap that must be addressed immediately and decisively.    We expect yo