        '21659',
        'UTR12 Re-execution Impact on all reports',
        'UTR12 Re-execution Impact on all reports',
        'Based on our phone call today, we have implemented an internal workaround. However, this workaround requires your decision before we can apply the adjustment in goAML Rajhi.    The first step is to determine the source from which the data should be read. There are two available options, each with a different impact on the system:    Option 1 – Read data directly from the Core system  In this approach, the data in goAML will always reflect the latest values available in the core system. However, this means that you will not be able to work on multiple goAML reports in parallel. Any manual adjustments would need to be applied each time when required, and reports would need to be processed sequentially.    Option 2 – Read data from the latest business adjustments  In this approach, the system will read data from the latest business adjustments entered, allowing you to work on multiple reports in parallel. However, any historical data adjustments entered previously would be removed, and goAML would only reflect the adjustments entered from this point forward.    The decision is entirely yours. Kindly share your preferred approach so that we can proceed accordingly with the required implementation.',
