        'Upload lists on test environment',
        'Dear ,  Regarding international blacklists,  please be advised that we are ready to install the service on the new server.    Thank you.',
        'Dear @Hla Ahmad - E-Services & CBS Services Officer,  Based on our web session, please note that the lists have been updated on the test environment of the new server and are currently running daily. We have also installed and configured the Oracle Client and Toad on the new server, and both are working as expected. In addition, the Automatic Loader service is currently running successfully.  Kindly be informed that the new server must have connectivity to the following links to ensure daily updates without any issues:  • OFAC(SDN): https://www.treasury.gov/ofac/downloads/sdn.xml    • OFAC(Non-SDN): https://www.treasury.gov/ofac/downloads/consolidated/consolidated.xml    • UN: https://scsanctions.un.org/resources/xml/en/consolidated.xml    • EU: https://webgate.ec.europa.eu/fsd/fsf/public/files/xmlFullSanctionsList_1_1/content?token=n00kb04g         Kindly check from your side and confirm so we can proceed with closing this ticket.',
