        'Creating ETL dataflows for the tables (PRO_RATE, BLK_LED & CHBK_REQ) on the FILL_ALL_TYPE ETL job.',
        'Dear Omar,  Based on our web session, kindly find below the status:     • Issue Reported by the customer: Creating ETL dataflows for the tables (PRO_RATE, BLK_LED & CHBK_REQ) on the FILL_ALL_TYPE ETL job.    • Status: Solved.    • Problem description: The bank requested the migration of core banking tables (PRO_RATE, BLK_LED, and CHBK_REQ) to the BankBI Data Warehouse. Additionally, there was a requirement to map the column LAS_TRA_DATE from the core Customer table to the data warehouse table PIO_CUSTOMERS.    • Action Taken – recommended solution: Based on our web session, kindly to be informed that the issue was resolved by creating ETL dataflows for the data warehouse tables (PIO_PRO_RATE, PIO_BLK_LED, and PIO_CHBK_REQ). The LAS_TRA_DATE column has also been mapped to the table BI_DWH.PIO_CUSTOMERS. Please note that data for this column will start appearing from April 22, 2026, onward.    Kindly check from your side and confirm to close this ticket.     Best Regards,',
