        'Study Office 2016 vs Office 365 Compatibility Issue',
        'I would like to highlight an issue we are currently facing regarding Office versions in use ,Some employees are still using Office 2016 .    Bank BI Application is only supported on Office 2016 and does not support 365.     As a result , we are encountering file compatibility issues when documents are modified on Office 2016 and then opened on office 365 .    Please advice on how you would like to proceed regarding this matter.',
        'Dear Samar    Based on my visit the office 365 is installed and working fine with SAP BI and SAP live office , as per our discussion with the finance team the issue was related to the past special option in the excel , the issue was resolved after using the available past option and the jor01 and tree reports generated successfully .    Please confirm.',
