(
        '21667',
        'Incorrect Alert Trigger – Threshold Mismatch',
        'Hello Dear,  Please note that an alert was triggered under the scenario “Daily - Individual / Jordanian: 1 transaction = 20,000 JOD within a day – March 2025” where the paid transaction is much lower than the configured threshold in the rule (20,000),    Kindly clarify the reason for this.',
        'Dear @Heba Bustami,    Based on our web session and investigation, please note that there is no issue related to the scenario itself.  We found that the scenario rules were updated/created on 12-Apr-2025, and it appears that a new rules was added to the scenario, as shown below. However, the alert you reported was generated before this date (27-Mar-2025) , which explains the difference in behavior.    Therefore, it seems that changes were made to the scenario rules after the reported alert was created.  Kindly review the alerts generated after 12-Apr-2025 and let us know if you still face any issues related to the scenario.',
