        '21714',
        'Review Customer Risk Rating – PEP Classification',
        'Review Customer Risk Rating – PEP Classification',
        'Dear @aml1@almosulbank.iq,    Based on our web session, please be informed that the customer risk score depends on all parameters configured in your risk matrix, not only on the customer’s occupation.    The system applies a calculation formula that evaluates each parameter separately by calculating its score based on the configured maximum score and assigned weight. After calculating the weighted score for each parameter, the system aggregates all parameter scores to generate the final percentage risk score. Accordingly, the customer classification is determined as High, Medium, or Low risk based on the configured thresholds defined in the “Risk Category.    For the mentioned customer, the calculated risk score is “54.0720”. According to the configured Risk Category thresholds, this value falls under the “Medium” risk classification, as shown in the pictures below:                  Please check from your side and don’t hestiate to reach out.',
