        '21718',
        'Study Vulnerabilities',
        'Study Vulnerabilities',
        'Dears,  Please find below the status update regarding the reported vulnerabilities:  1. Regarding the ‘Apache Tomcat Default Files’ vulnerability (Port: 8080): Default and example files in Apache Tomcat should be removed or disabled to prevent unnecessary exposure and reduce the attack surface.    Example: Remove default applications and files such as Tomcat sample apps and welcome pages from the web root directory (e.g., /examples, /docs, /manager if not required).     2. Regarding the ‘SSL Medium Strength Cipher Suites Supported (SWEET32)’ vulnerability (Port: 443): Medium-strength cipher suites vulnerable to the SWEET32 attack should be disabled and replaced with strong, modern cipher suites to ensure secure encryption.    3. Regarding the ‘HTTP Methods Allowed (per directory)’ vulnerability (Port: 80): Port 80 should be disabled, as only secure communication over Port 443 (HTTPS) will be used in the test environment.   Please note that the remaining vulnerabilities should be addressed from your side, as our scope is limited to handling the following ports only:    - 80  - 8080  - 8443  - 443     Thank you.',
