(
        '21745',
        'Monthly Charities Scenario Alerts Issue',
        'Dear Pio-Tech Team,    Please find attached sample cases showing that some alerts triggered under the below scenario:  “Monthly – Charities payments = 10,000 JD within 1 month – March 2025”    are capturing billers from the medical sector instead of charities.  Kindly advise on the reason and take the necessary corrective action.',
        'Dear @Heba Bustami,    Based on our web session, please be informed that the issue was related to the approach used the parameters while creating the scenario. The rule related to the category name was reading the value associated with another institution (”2” DOT JO) instead of the (MFEP”1”) institution, as shown in the pictures below:    ? Sample transaction for your customer provided:                 The category with value “10” is related to “Charities” under institution 2 “DOT JO” . However, when the engine runs for institution 1, the same value “10” corresponds to the description “Medical and Health” .As a result, the scenario was matching against the wrong category description.    To resolve the issue, we modified the category value for “Charities” under institution 1 from “10” to “24” within the scenario configuration as shown in the picture below:          Accordingly, the scenario should now work as expected.Additionally, please be informed that we have modified all categories within this parameter to ensure that only the category names related to institution “1” (MFEP) are being read.    Kindly continue monitoring the scenario results at the beginning of the upcoming month and share your feedback accordingly.',
        '2026-05-05T00:00:00.000Z'::timestamptz,
