        'Dear Mohammed    I would like to request approval to upgrade our DMS DB Windows Server 2016 Standard.  Windows Server 2016 is currently in Extended Support, and Microsoft no longer provides mainstream updates. To ensure continued security, compliance, and system stability,  it is recommended to upgrade to a newer supported version OS 2019 or 2022 before the end of support in 2027.    Note// The Operation System of DMS app server is 2019 standard.',
