(
        '21847',
        'Login issue on test',
        'Dears,    Kindly note that when trying to login in into Bank BI test server I cannot chose a language and can’t login.     Please advise.',
        'Based on our web session, kindly find below the status:     • Issue Reported by the customer: Login issue on test     • Status: Solved     • Problem description: Login issue on test     Action Taken – recommended solution: Based on our session, we identified that the issue was related to the SSL setting in the system configuration.    SSL is a security protocol used to establish a secure connection between the application and the server. In this case, the configuration was set incorrectly, causing the connection to use HTTP instead of HTTPS, which affected the login process in the test environment and could potentially impact other users as well.    After updating the SSL configuration to use the correct protocol, the issue was resolved successfully, and the system is now functioning as expected.    ?  Kindly check and confirm so we may proceed with closing the ticket.     kind regards ,',
        '2026-05-17T00:00:00.000Z'::timestamptz,
