(
        '21871',
        'password change after first login',
        'password change after first login , before the first login it was work normally but now it is not working',
        'Dear @Dashti A. Mohamed,  Based on our web session, please note that there does not appear to be any issue related to the password itself. The option “Apply Password Restriction” was enabled, as agreed, to ensure that users are prompted to change their password upon first login.  However, from your side, the prompt to change the password at first login is not being displayed. This behavior is expected in this case, as the password was changed via the Admin Panel.  The system logic works as follows: when the “Apply Password Restriction” option is enabled, the user will only be prompted to change the password at first login if the password has not already been modified. Since the password was already changed through the Admin Panel, the condition for triggering the prompt is not met.  Accordingly, this is the expected behavior based on the current configuration.',
        '2026-05-19T00:00:00.000Z'::timestamptz,
