        'Check DR Site Test',
        'Dears,    kindly note that we are requesting your help with testing DR site for BANK-BI and make sure that everything is up to date with production. including AML, RBA, BI reports, etc. please advise on your availability and next step ASAP.    thanks',
        'Dear Mr. Mohammad,    Thank you for your time.    As discussed during the meeting, the DR application server is running the same SAP BI version as the production server. However, it appears that the number of BI reports is not matching the production environment.    To synchronize the DR site with the live environment, there are two available approaches:  • VM replication (recommended)  • Manual export/import of SAP BI objects    As agreed, you will verify whether VM replication is applicable and confirm once it has been completed.    In the meantime, we will arrange a session to review the ETL DR server.',
