        '21856',
        'Upgrade SAP IPs and DS',
        'Dear Nawaf    Kindly find our response in the “Note” column , please refer to bank DBA team regarding Microsoft SQL server vulnerabilities and infa. Team for MobaXterm vulnerability.  @Asaad Omar kindly arrange to upgrade the SAP IPS and SAP DS to mentioned version during this week.    PluginPlugin NameSeverityProtocolPortNote  15901SSL Certificate ExpiryMediumTCP8391default port used by Microsoft SQL Server Integration Services (SSIS) Scale Out Master to communicate with Scale Out Workers  35291SSL Certificate Signed Using Weak Hashing AlgorithmMediumTCP8391default port used by Microsoft SQL Server Integration Services (SSIS) Scale Out Master to communicate with Scale Out Workers  156860Apache Log4j 1.x Multiple VulnerabilitiesCriticalTCP445SAP Data Services and SAP Cloud Integration for data services are not impacted by the CVEs listed in Log4j 2.x and Log4j 1.x above since the products do not use the vulnerable classes in their functionality.  182252Apache Log4j SEoL (<= 1.x)CriticalTCP0Upgrade SAP IPS and SAP DS to the latest version   SAP IPS 4.3 sp5 patch 5 and SAP DS 4.3 sp3 patch 11  192156Mobatek MobaXterm < 22.3 (CVE-2022-38337)CriticalTCP445Not related to SAP, Related to The integrated SFTP client browser (based on the SecureBlackbox library) within MobaXterm.',
        'Dear @Nawaf Iskandarani,    Based on our web session, kindly find below the status:     • Issue Reported by the customer: Upgrade SAP IPs and DS.     • Status: Done.     • Problem description: An upgrade was required for SAP IPs and Data Services (DS).    • Action Taken – recommended solution: Based on our web session, please note that the required upgrades for SAP IPs and DS have been completed successfully, and the installation has been upgraded to the latest version successfully.         Kindly also note that Port 80 (HTTP) has been removed successfully, and the server is now operating through Port 443 (HTTPS).     Kindly check from your side and confirm so we can proceed with closing the ticket.',
