(
        '21907',
        'Audit Requirements',
        'Dears;  Based on Auditors requirements, kindly find the below points need to be done on AML System:  1- Closure comments field should be Mandatory t be filled.  2- Clarify whether separate thresholds can be configured for different customer/business segments.  3- Provide a list of inactive or ineffective scenarios that did not generate alerts during the audit period (Year 2025).  4- Confirm the data fields transferred from the Core Banking System to Pio-Tech system for TM purposes.  please treat this matter as urgent and critical.  Thanks.',
        'Dear @Maryam Dawood,     Thank you for joining the meeting and discussing the raised points in detail.     Regarding our discussion, please find our responses below:     1. Closure Comments Field Should Be Mandatory:     As discussed, our development has worked on adding a Comments button within the actions section, allowing users to add comments that can be viewed by the next approval level, facilitating better tracking and review of alert-related remarks.  This enhancement requires the installation of the latest release in the test environment first to ensure that it functions as expected before being deployed to the production environment.     2. Separate Thresholds for Different Customer/Business Segments     As discussed, to proceed with this requirement, we need you to provide the list of customer/business segments from your side. Based on the provided segments, we can create dedicated scenarios, similar to the approach previously implemented for the employee-related scenario.     3. List of Inactive or Ineffective Scenarios During the Audit Period (Year 2025)     The requested information has been provided. Kindly review it and let us know if you require any further assistance or clarification.     4. Data Fields Transferred from the Core Banking System to the Pio-Tech System for TM Purposes     As discussed, we retrieve all relevant customer, account, transaction, and other required data available in your Core Banking System and transfer it to the Pio-Tech system .     In additionwe have provided the engine details that retrieve the transaction fields from your Core Banking System for your reference. Kindly review the provided information and let us know if you have any questions or require further clarification.        Please feel free to reach out if you need any additional information.',
