(
        '21938',
        'ETL job issue',
        'ETL job issue',
        'Dear Mohammad,  Good afternoon, I hope this email finds you well.    Based on my investigation of the reported issue, the ODI Load Plan was successfully triggered by the scheduler on June 02, 2026, at 01:31 AM as expected. However, the load plan did not start its execution immediately and remained in a pending state until 01:36 PM, when I connected to the server and interacted with the ODI Agent Command Prompt (CMD) window. At that point, the ODI Agent resumed processing and the load plan started successfully.    After reviewing the ODI Agent logs and the server configuration, it appears that the issue was related to the ODI Agent running within an interactive Windows Command Prompt (CMD) session. The CMD window had the Windows QuickEdit feature enabled, which can cause a running process to become suspended if the console unintentionally enters selection mode due to user interaction. As a result, the ODI Agent may stop processing incoming requests while remaining active, preventing scheduled load plans from starting at their designated time.    To prevent the issue from reoccurring, QuickEdit Mode and Insert Mode were disabled for the Command Prompt session used by the ODI Agent, and the ODI Agent was restarted to ensure that the new settings were applied successfully. These changes help prevent the CMD window from unintentionally suspending the ODI Agent process due to console interactions.',
        '2026-06-03T00:00:00.000Z'::timestamptz,
        '2026-06-03T00:00:00.000Z'::timestamptz,
