(
        '21928',
        'Check validation of scenario 1000033',
        'Dear Piotech Team,  I hope this email finds you well.  We are writing to report a critical technical issue regarding our AML transaction monitoring system.  Based on our comprehensive review of all system alerts and their effectiveness, we discovered that the "Sender and Beneficiary are the Same Person" scenario has failed to generate any alerts from February 9, 2025, up to the present date, despite the scenario being active on the system.  Our analysis confirms that during this period, there were 9,948 transactions executed on our core system that strictly match the criteria of this scenario and should have triggered alerts.  Given the regulatory importance of this scenario under the Central Bank of Jordan (CBJ) regulations, this matter is highly urgent. Please investigate this issue immediately to identify the root cause and advise us on why these alerts were not generated. Specifically, please check if there is a bug in the rule logic, an error in field mapping, or a failure in the data ingestion process.  Scenario Code : 1000033  Rule Number : 1000040  Crucial Note: Please be advised that prior to February 9, 2025, this scenario was functioning correctly and generating alerts as expected on the system. The complete cessation of alerts occurred precisely after this date.  We expect a prompt update and an immediate resolution',
        'Dear @Laith Al-Omari,  Based on our web session and our investigation, please note that there does not appear to be any issue with the scenario or rule configuration itself. After reviewing the data, we found that the latest date on which customers matched the scenario rules was in 25-Jun-2025. It appears that there was an issue related to reading the Deptor Number on that specific date, which prevented the expected alerts from being generated.  To verify the behavior, we re-ran the AML engine for 25-Jun-2025, and the scenario generated alerts successfully as expected. This confirms that the scenario and its rules are functioning correctly.  Furthermore, our analysis showed that no customers matched the scenario rules after 26-Jun-2025. Therefore, the absence of alerts after that date is expected, as there were no transactions or customers meeting the defined scenario criteria.  Please let us know if you have any specific customer or transaction examples that you believe should have matched the scenario, and we will be happy to investigate them further.',
        '2026-06-03T00:00:00.000Z'::timestamptz,
        '2026-06-08T00:00:00.000Z'::timestamptz,
        '015a7170-65d3-490b-bd00-2c41faabf8f9'::uuid,
        'fda4ba3b-e13b-4a9c-a1b2-fb5263eaee4a'::uuid,
        '92e761b0-ddea-44a3-8f7a-53116cff371a'::uuid,
        'Asaad Omar',
        '8066aa61-7985-4be8-92cc-490b0d3f4b95'::uuid,
        '150f9737-5aba-48a6-9303-0af9cbbb304f'::uuid
      ),
(
        '21929',
        'AML system training session',
        'AML system training session',
        'Dears,    Thank you for attending the AML training sessions. We hope that these sessions were beneficial and that all your questions were addressed.    This email is to confirm that we have provided your team with training on the AML system and discussed all related functionalities and processes.    Additionally, regarding the Translator Tool, please note that this is a paid service designed to translate customer names from Arabic to English, facilitating their use in the screening process and improving screening effectiveness. If you wish to activate this feature, please confirm, and we will forward your request to the responsible department for further processing.    For the screening process, please find the details below:    • My colleague @Mohammad Al-Katry will proceed with activating the list loading process starting at 8:00 AM, as per your request. After that, we will execute the screening process in the test environment as follows:     1. First run: Full screening for all customers.   2. Second run: Delta screening (next day) and approval for production use only.       ? Please review the features below and provide us with your preferred choice:    Regarding the Closed AML Alerts Report, please confirm your preferred approach for alert appearance:    1. Based on the alert work end date.   2. Based on the date the alert appears in the system.     Regarding the Alert Locking Feature, please advise your preferred approach:    1. Enable: Any user who opens an alert will automatically lock it, preventing other users from accessing it simultaneously.   2. Disable: Any user can open and work on an alert without affecting access by other users.       Should you have any questions or require any further clarification, please don’t hesitate to contact us.',
        '2026-06-03T00:00:00.000Z'::timestamptz,
