        'Yield Analysis "incorrect value for the Avg_equ_bal',
        'Yield Analysis "incorrect value for the Avg_equ_bal',
        'Dear @Archana A.D. Dharmaraj,    Based on our web session, the issue was related to the column CUR_CODE not being included in the primary key of the table BI_DWH.PIO_LED_BALA_AVG.    To resolve the issue, the existing primary key constraint had to be dropped using the following query    ALTER TABLE BI_BWH.PIO_LED_BALA_AVG  DROP CONSTRAINT BI_DWH.PIO_LED_BALA_AVG_PK;   After that, the table should be altered again to include CUR_CODE in the primary key using the query below:  ALTER TABLE BI_DWH.PIO_LED_BALA_AVG ADD (   CONSTRAINT PIO_LED_BALA_AVG_PK   PRIMARY KEY   (DAY_DATE, COUNTRY_CODE, INST_CODE, LED_CODE,CUR_CODE)   USING INDEX BI_DWH.PIO_LED_BALA_AVG_PK   ENABLE VALIDATE);',
