(
        '21932',
        'Study vulnerabilities',
        'Study vulnerabilities',
        'Dear @Aya Hany,    Please note that based on our assessment the reported CVEs are not applicable to the current SAP BusinessObjects environment and do not impact the system for the reasons outlined below:  • CVE-2026-43512: *38 Not Impacted - Related to Digest Authentication issue - which is not used by Bobj applications  • CVE-2026-43513: *39 Not Impacted - Related to LockoutRealm usage -which is not configured on SAP Bobj bundled tomcat  • CVE-2026-43514: *40 Not Impacted - Related to AJP connectivity / also low priority - we do not need AJP connectors configured  • CVE-2026-43515: *41 Not Impacted - Applicable when using security-constraint in web.xml - which we ship already commented out.  • CVE-2026-42498: *37 Not Impacted - We use traditional HTTP/HTTPS request-response model - not websockets - so not impacted  • CVE-2026-41293: *36 Not Impacted- Improper input validation / HTTP2 request headers - HTTP/2 option exists but we do not ship with this configuration and use HTTP 1.1  • CVE-2026-41284: *35 Not Impacted- we do not recommend allocating "unlimited" resources - so this may not be directly impacting SAP Bobj products',
        '2026-06-03T00:00:00.000Z'::timestamptz,
