(
        '21933',
        'Resolve vulnerabilities on SAP BI',
        'Resolve vulnerabilities on SAP BI',
        'Dear Moses     SAP replayed to the Vulnerabilities reports , kindly find below their response:      Hi Raed,    I have reviewed all the pages. Most of them are just information. Below is my analysis    Vulnerability 1 - 150004 Predictable Resource Location Via Forced Browsing    Response: We reviewed the reported URL and confirmed that the SAP BusinessObjects CMC application requires authentication before access is granted. The reported path is a standard SAP BI web application URL and does not expose directory contents, configuration files, or sensitive information. Therefore, this finding appears to be a false positive generated by automated forced-browsing detection. No unauthorized access or information disclosure was observed during validation. Without a valid credentials, the URL can''t be logged in    Vulnerability 2 - 150246 Path-relative stylesheet import (PRSSI) vulnerability    Response: Since BOE/CMC and BOE/BI are login pages for Central Management Console (CMC) and BI Launchpad (BI) applications, X-FRAME-OPTIONS header is not present in the response. Once login is done, XFO headers is appended to the response in further pages after login.    Refer to Official SAP Note: 2939065 - X-Frame-Options Header not set in BI Launchpad and CMC logon page    Also please refer to the following SAP Note for enabling X-Content-Type-Options - 3445410 - How to enable X-Content-Type-Options nosniff in 4.3 SP3+      Vulnerability 3 - 150124 Clickjacking - Framable Page    Response: Refer to following SAP Note which states - It is not always necessary to receive the X-Frame-Options header as ''SAMEORIGIN'' or ''DENY'' for each response. Hence, this vulnerability is false positive. 3448083 - Clickjacking X-Frame-Options header. I recommend you apply SAP Note: 3445410 - How to enable X-Content-Type-Options nosniff in 4.3 SP3+ and rescan.    Also please note: SAP BusinessObjects Business Intelligence Platform 4.x (4.3) and 20xx (2025) do not support CSP headers, as a few browsers will block various BI content on addition of CSP headers. Refer to SAP Note: 2406350 - CSP (Content Security Policy) compliance --- BI Launchpad and CMC does not support CSP policy      Vulnerability 4 - 150112 Sensitive form field has not disabled autocomplete    Response: This is due to browser''s autofill feature which saves the values of form data. The forms and password autofill feature is not controlled by BO and there is no way that we can disable this from server side. You can do this by disabling the autofill feature from the browser itself. Reference SAP Note: 2444487 - How to Disable username auto fill in Central Management Console/BI Launchpad      Vulnerability 5 - 150319 Weak Cookies in Use    Response: This is false Positive, when HTTPS is enabled in SAP BI, there won''t be any Weak Cookies. For more information you can check the following SAP Note: 1898697 - httponly and secure flag options for BI Launchpad cookies    Regards,  Aamir',
        '2026-06-03T00:00:00.000Z'::timestamptz,
        '2026-06-17T00:00:00.000Z'::timestamptz,
        '015a7170-65d3-490b-bd00-2c41faabf8f9'::uuid,
